import math


def count_binary_seq(n):
    """Write a function to find the count of all binary sequences of length 2n such that sum of first n bits is same as sum of last n bits."""
    # For each k, there are C(n, k) choices for the first half to have
    # k ones and C(n, k) choices for the second half, giving
    # sum_k C(n, k)^2 = C(2n, n) such sequences (Vandermonde's identity).
    # math.comb raises ValueError for negative n and TypeError for
    # non-integer n.
    return math.comb(2 * n, n)
